1	const std = @import("std");
2	const datatype = @import("datatype.zig");
3	const array_ref_mod = @import("array/array_ref.zig");
4	const array_data = @import("array/array_data.zig");
5	const array_mod = @import("array/array.zig");
6	const buffer = @import("buffer.zig");
7	const bitmap = @import("bitmap.zig");
8	
9	pub const DataType = datatype.DataType;
10	pub const ArrayRef = array_ref_mod.ArrayRef;
11	pub const ArrayData = array_data.ArrayData;
12	
13	pub const ConcatArrayError = error{ OutOfMemory, InvalidInput, UnsupportedType };
14	pub const Error = ConcatArrayError || array_data.ValidationError;
15	
16	pub fn concatArrayRefs(
17	    allocator: std.mem.Allocator,
18	    data_type: DataType,
19	    parts: []const ArrayRef,
20	) Error!ArrayRef {
21	    if (parts.len == 0) return error.InvalidInput;
22	
23	    // Flat layouts: two passes over `parts`, each output buffer allocated once; checks part types itself.
24	    if (try concatManyFlat(allocator, data_type, parts)) |out| return out;
25	
26	    // Nested layouts check the part types themselves, in the pass that reads the parts.
27	    if (isNestedLayout(data_type)) return concatManyNested(allocator, data_type, parts);
28	
29	    for (parts) |part| {
30	        if (!datatype.dataTypeEql(part.data().data_type, data_type)) return error.InvalidInput;
31	    }
32	
33	    if (parts.len == 1) {
34	        // Single part still returns a fresh, compacted copy (offset 0), as before.
35	        var empty = try parts[0].slice(0, 0);
36	        defer empty.release();
37	        return concatTwoArrayRefs(allocator, empty, parts[0]);
38	    }
39	
40	    // View types: balanced pairwise merge, O(total_len * log(parts.len)).
41	    var level = try mergePairs(allocator, parts);
42	    while (level.items.len > 1) {
43	        const next = mergePairs(allocator, level.items) catch |err| {
44	            releaseAll(allocator, &level);
45	            return err;
46	        };
47	        releaseAll(allocator, &level);
48	        level = next;
49	    }
50	    const out = level.items[0];
51	    level.deinit(allocator);
52	    return out;
53	}
54	
55	/// Concatenates `refs` two at a time; an odd trailing ref is retained as-is.
56	fn mergePairs(allocator: std.mem.Allocator, refs: []const ArrayRef) Error!std.ArrayList(ArrayRef) {
57	    var out = try std.ArrayList(ArrayRef).initCapacity(allocator, (refs.len + 1) / 2);
58	    errdefer releaseAll(allocator, &out);
59	    var i: usize = 0;
60	    while (i + 1 < refs.len) : (i += 2) {
61	        out.appendAssumeCapacity(try concatTwoArrayRefs(allocator, refs[i], refs[i + 1]));
62	    }
63	    if (i < refs.len) out.appendAssumeCapacity(refs[i].retain());
64	    return out;
65	}
66	
67	fn releaseAll(allocator: std.mem.Allocator, list: *std.ArrayList(ArrayRef)) void {
68	    for (list.items) |*ref| ref.release();
69	    list.deinit(allocator);
70	}
71	
72	fn concatTwoArrayRefs(
73	    allocator: std.mem.Allocator,
74	    left: ArrayRef,
75	    right: ArrayRef,
76	) Error!ArrayRef {
77	    if (!datatype.dataTypeEql(left.data().data_type, right.data().data_type)) return error.InvalidInput;
78	
79	    if (try concatManyFlat(allocator, left.data().data_type, &[_]ArrayRef{ left, right })) |out| return out;
80	
81	    const dt = left.data().data_type;
82	    const layout_dt = storageDataType(dt);
83	    var merged_storage = try switch (layout_dt) {
84	        .string_view => try concatStringViewArray(allocator, left.data(), right.data()),
85	        .binary_view => try concatBinaryViewArray(allocator, left.data(), right.data()),
86	        else => error.UnsupportedType,
87	    };
88	
89	    if (datatype.dataTypeEql(dt, layout_dt)) return merged_storage;
90	    const retagged = try retagArrayRefDataType(allocator, merged_storage, dt);
91	    merged_storage.release();
92	    return retagged;
93	}
94	
95	pub fn storageDataType(dt: DataType) DataType {
96	    return switch (dt) {
97	        .extension => |ext| storageDataType(ext.storage_type.*),
98	        else => dt,
99	    };
100	}
101	
102	fn retagArrayRefDataType(allocator: std.mem.Allocator, src: ArrayRef, out_dt: DataType) error{OutOfMemory}!ArrayRef {
103	    var out = src.data().*;
104	    out.data_type = out_dt;
105	    return ArrayRef.fromBorrowed(allocator, out);
106	}
107	
108	fn viewDataCapacityHint(data: *const ArrayData) usize {
109	    if (data.buffers.len >= 3) return data.buffers[2].len();
110	    return 0;
111	}
112	
113	fn concatStringViewArray(
114	    allocator: std.mem.Allocator,
115	    left: *const ArrayData,
116	    right: *const ArrayData,
117	) Error!ArrayRef {
118	    try left.validateLayout();
119	    try right.validateLayout();
120	    const total_len = std.math.add(usize, left.length, right.length) catch return error.InvalidInput;
121	    const data_capacity = std.math.add(usize, viewDataCapacityHint(left), viewDataCapacityHint(right)) catch return error.InvalidInput;
122	
123	    var builder = try array_mod.StringViewBuilder.init(allocator, total_len, data_capacity);
124	    defer builder.deinit();
125	
126	    const left_view = array_mod.StringViewArray{ .data = left };
127	    var i: usize = 0;
128	    while (i < left.length) : (i += 1) {
129	        if (left_view.isNull(i)) {
130	            builder.appendNull() catch |err| return mapViewBuilderError(err);
131	        } else {
132	            const value = left_view.value(i) catch return error.InvalidInput;
133	            builder.append(value) catch |err| return mapViewBuilderError(err);
134	        }
135	    }
136	
137	    const right_view = array_mod.StringViewArray{ .data = right };
138	    i = 0;
139	    while (i < right.length) : (i += 1) {
140	        if (right_view.isNull(i)) {
141	            builder.appendNull() catch |err| return mapViewBuilderError(err);
142	        } else {
143	            const value = right_view.value(i) catch return error.InvalidInput;
144	            builder.append(value) catch |err| return mapViewBuilderError(err);
145	        }
146	    }
147	
148	    var out = builder.finish() catch |err| return mapViewBuilderError(err);
149	    errdefer out.release();
150	    try out.data().validateLayout();
151	    return out;
152	}
153	
154	fn concatBinaryViewArray(
155	    allocator: std.mem.Allocator,
156	    left: *const ArrayData,
157	    right: *const ArrayData,
158	) Error!ArrayRef {
159	    try left.validateLayout();
160	    try right.validateLayout();
161	    const total_len = std.math.add(usize, left.length, right.length) catch return error.InvalidInput;
162	    const data_capacity = std.math.add(usize, viewDataCapacityHint(left), viewDataCapacityHint(right)) catch return error.InvalidInput;
163	
164	    var builder = try array_mod.BinaryViewBuilder.init(allocator, total_len, data_capacity);
165	    defer builder.deinit();
166	
167	    const left_view = array_mod.BinaryViewArray{ .data = left };
168	    var i: usize = 0;
169	    while (i < left.length) : (i += 1) {
170	        if (left_view.isNull(i)) {
171	            builder.appendNull() catch |err| return mapViewBuilderError(err);
172	        } else {
173	            const value = left_view.value(i) catch return error.InvalidInput;
174	            builder.append(value) catch |err| return mapViewBuilderError(err);
175	        }
176	    }
177	
178	    const right_view = array_mod.BinaryViewArray{ .data = right };
179	    i = 0;
180	    while (i < right.length) : (i += 1) {
181	        if (right_view.isNull(i)) {
182	            builder.appendNull() catch |err| return mapViewBuilderError(err);
183	        } else {
184	            const value = right_view.value(i) catch return error.InvalidInput;
185	            builder.append(value) catch |err| return mapViewBuilderError(err);
186	        }
187	    }
188	
189	    var out = builder.finish() catch |err| return mapViewBuilderError(err);
190	    errdefer out.release();
191	    try out.data().validateLayout();
192	    return out;
193	}
194	
195	fn mapViewBuilderError(err: anyerror) ConcatArrayError {
196	    return switch (err) {
197	        error.OutOfMemory => error.OutOfMemory,
198	        else => error.InvalidInput,
199	    };
200	}
201	
202	const FlatKind = union(enum) {
203	    null_type,
204	    boolean,
205	    fixed: usize,
206	    binary32,
207	    binary64,
208	};
209	
210	fn flatKind(layout_dt: DataType) Error!?FlatKind {
211	    return switch (layout_dt) {
212	        .null => .null_type,
213	        .bool => .boolean,
214	        .uint8, .int8 => .{ .fixed = 1 },
215	        .uint16, .int16, .half_float => .{ .fixed = 2 },
216	        .uint32, .int32, .float, .date32, .time32, .interval_months, .decimal32 => .{ .fixed = 4 },
217	        .uint64, .int64, .double, .date64, .time64, .timestamp, .duration, .interval_day_time, .decimal64 => .{ .fixed = 8 },
218	        .decimal128, .interval_month_day_nano => .{ .fixed = 16 },
219	        .decimal256 => .{ .fixed = 32 },
220	        .fixed_size_binary => |fsb| .{ .fixed = std.math.cast(usize, fsb.byte_width) orelse return error.InvalidInput },
221	        .dictionary => |d| .{ .fixed = d.index_type.bit_width / 8 }, // indices; parts share one dictionary
222	        .string, .binary => .binary32,
223	        .large_string, .large_binary => .binary64,
224	        else => null,
225	    };
226	}
227	
228	/// N-ary concat for flat layouts (null, bool, fixed-width, binary/string) in two passes over
229	/// `parts`: one sizing pass (types, rows, bytes, may-have-nulls), then one copy pass that writes
230	/// validity and values of each part together. Nulls are counted once on the output bitmap.
231	/// `parts` are ArrayRefs or Part windows. Dictionary parts must share one dictionary.
232	/// Returns null for nested and view types and for dictionaries that differ.
233	fn concatManyFlat(allocator: std.mem.Allocator, dt: DataType, parts: anytype) Error!?ArrayRef {
234	    const kind = (try flatKind(storageDataType(dt))) orelse return null;
235	    var view: ArrayData = undefined;
236	    const dictionary = if (storageDataType(dt) == .dictionary) partData(&parts[0], &view).dictionary else null;
237	
238	    // Copying a DataType for dataTypeEql touches a second cache line of every part's node;
239	    // for parameterless types the tag compare is the whole equality.
240	    const tag_only = switch (dt) {
241	        .null, .bool, .uint8, .int8, .uint16, .int16, .uint32, .int32, .uint64, .int64, .half_float, .float, .double, .string, .binary, .large_string, .large_binary, .date32, .date64 => true,
242	        else => false,
243	    };
244	    var total_len: usize = 0;
245	    var total_data: usize = 0;
246	    var maybe_nulls = false;
247	    for (parts) |*part| {
248	        const d = partData(part, &view);
249	        if (std.meta.activeTag(d.data_type) != std.meta.activeTag(dt)) return error.InvalidInput;
250	        if (!tag_only and !datatype.dataTypeEql(d.data_type, dt)) return error.InvalidInput;
251	        if (dictionary) |dict| {
252	            if (d.dictionary == null or d.dictionary.?.node != dict.node) return null;
253	        }
254	        total_len = std.math.add(usize, total_len, d.length) catch return error.InvalidInput;
255	        maybe_nulls = maybe_nulls or ((d.null_count orelse 1) != 0 and d.buffers.len > 0 and !d.buffers[0].isEmpty());
256	        const r: ByteRange = switch (kind) {
257	            .binary32 => try binaryDataRange(i32, d),
258	            .binary64 => try binaryDataRange(i64, d),
259	            else => .{ .start = 0, .end = 0 },
260	        };
261	        total_data = std.math.add(usize, total_data, r.end - r.start) catch return error.InvalidInput;
262	    }
263	    if (kind == .null_type) {
264	        return try ArrayRef.fromOwnedInlineBuffers(allocator, .{ .data_type = dt, .length = total_len, .null_count = total_len, .buffers = &.{} });
265	    }
266	
267	    // Every output buffer is allocated once. Validity only if some part may hold a null.
268	    const used = bitmap.byteLength(total_len);
269	    const width: usize = switch (kind) {
270	        .fixed => |w| w,
271	        .binary32 => @sizeOf(i32),
272	        .binary64 => @sizeOf(i64),
273	        else => 0,
274	    };
275	    const values_len = switch (kind) {
276	        .boolean => used,
277	        .fixed => std.math.mul(usize, total_len, width) catch return error.InvalidInput,
278	        else => (total_len + 1) * width, // offsets
279	    };
280	    const is_binary = kind == .binary32 or kind == .binary64;
281	    if (total_data > (if (kind == .binary32) @as(usize, std.math.maxInt(i32)) else @as(usize, std.math.maxInt(i64)))) return error.InvalidInput;
282	    var validity = try buffer.OwnedBuffer.init(allocator, if (maybe_nulls) used else 0);
283	    errdefer validity.deinit();
284	    // Bool values are OR-ed bits (need zeroed memory); other slots are all written below.
285	    var values = try (if (kind == .boolean) buffer.OwnedBuffer.init(allocator, values_len) else buffer.OwnedBuffer.initUninit(allocator, values_len + 16));
286	    errdefer values.deinit();
287	    var data_bytes = try buffer.OwnedBuffer.initUninit(allocator, total_data + 16); // wildCopy slack
288	    errdefer data_bytes.deinit();
289	
290	    var row: usize = 0;
291	    var byte_pos: usize = 0;
292	    for (parts) |*part| {
293	        const d = partData(part, &view);
294	        if (maybe_nulls) try appendValidityBits(validity.data, row, d);
295	        switch (kind) {
296	            .null_type => unreachable,
297	            .boolean => {
298	                try requireBufferCount(d, 2);
299	                try requireBitmapBits(d.buffers[1], d.offset + d.length);
300	                bitmap.copyBits(values.data, row, d.buffers[1].data, d.offset, d.length);
301	            },
302	            .fixed => {
303	                try requireBufferCount(d, 2);
304	                const bytes = try dataBytesForFixedWidth(d, width);
305	                wildCopy(values.data[row * width ..], d.buffers[1].data, d.offset * width, bytes.len);
306	            },
307	            .binary32 => byte_pos = try copyBinaryPart(i32, values.typedSlice(i32), data_bytes.data, row, byte_pos, d),
308	            .binary64 => byte_pos = try copyBinaryPart(i64, values.typedSlice(i64), data_bytes.data, row, byte_pos, d),
309	        }
310	        row += d.length;
311	    }
312	    if (kind == .binary32) values.typedSlice(i32)[0] = 0;
313	    if (kind == .binary64) values.typedSlice(i64)[0] = 0;
314	    const null_count = if (maybe_nulls) total_len - bitmap.countSetBit(validity.data, total_len) else 0;
315	
316	    var bufs: [3]array_data.SharedBuffer = .{ array_data.SharedBuffer.empty, array_data.SharedBuffer.empty, array_data.SharedBuffer.empty };
317	    errdefer for (&bufs) |*b| b.release();
318	    if (null_count == 0) validity.deinit() else bufs[0] = try validity.toShared(used);
319	    bufs[1] = try values.toShared(values_len);
320	    if (is_binary) bufs[2] = try data_bytes.toShared(total_data) else data_bytes.deinit();
321	    const buf_count: usize = if (is_binary) 3 else 2;
322	
323	    const data = ArrayData{
324	        .data_type = dt,
325	        .length = total_len,
326	        .null_count = null_count,
327	        .buffers = bufs[0..buf_count],
328	        .dictionary = dictionary,
329	    };
330	    try data.validateLayout();
331	    const out = try ArrayRef.fromOwnedInlineBuffers(allocator, data);
332	    if (dictionary) |dict| _ = dict.retain();
333	    return out;
334	}
335	
336	/// Rows [start, start + len) of `ref`: nested concat records every part's child windows in one
337	/// pass over the parts and hands them down instead of allocating an ArrayRef slice per window.
338	const Part = struct { ref: ArrayRef, start: usize, len: usize };
339	
340	/// A part's rows (`part` points to an ArrayRef or a Part); a partial window is sliced into `view`.
341	inline fn partData(part: anytype, view: *ArrayData) *const ArrayData {
342	    if (@TypeOf(part) == *const ArrayRef) return part.data();
343	    const d = part.ref.data();
344	    if (part.start == 0 and part.len == d.length) return d;
345	    view.* = d.slice(part.start, part.len);
346	    return view;
347	}
348	
349	fn isNestedLayout(dt: DataType) bool {
350	    return switch (storageDataType(dt)) {
351	        .list, .large_list, .map, .fixed_size_list, .struct_ => true,
352	        else => false,
353	    };
354	}
355	
356	/// Concat of windows: flat and nested layouts N-ary, other layouts through slices + concatArrayRefs.
357	fn concatParts(allocator: std.mem.Allocator, dt: DataType, parts: []const Part) Error!ArrayRef {
358	    if (try concatManyFlat(allocator, dt, parts)) |out| return out;
359	    if (isNestedLayout(dt)) return concatManyNested(allocator, dt, parts);
360	    const refs = try allocator.alloc(ArrayRef, parts.len);
361	    var made: usize = 0;
362	    defer {
363	        for (refs[0..made]) |*ref| ref.release();
364	        allocator.free(refs);
365	    }
366	    for (parts, refs) |*part, *ref| {
367	        ref.* = try part.ref.slice(part.start, part.len);
368	        made += 1;
369	    }
370	    return concatArrayRefs(allocator, dt, refs);
371	}
372	
373	/// N-ary concat for list/large_list/map/fixed_size_list/struct (`parts`: ArrayRefs or Parts).
374	/// Pass 1 checks the parts and records every child's window, pass 2 writes validity and rebased
375	/// list offsets, then each child is concatenated once from its windows.
376	fn concatManyNested(allocator: std.mem.Allocator, dt: DataType, parts: anytype) Error!ArrayRef {
377	    const layout = storageDataType(dt);
378	    const n_children: usize = if (layout == .struct_) layout.struct_.fields.len else 1;
379	    const offset_width: usize = switch (layout) {
380	        .list, .map => @sizeOf(i32),
381	        .large_list => @sizeOf(i64),
382	        else => 0,
383	    };
384	    const max_child: usize = if (offset_width == 4) std.math.maxInt(i32) else std.math.maxInt(i64);
385	    const buf_count: usize = if (offset_width > 0) 2 else 1;
386	    const n = parts.len;
387	
388	    // windows[c * n + p]: the rows of child c that part p covers.
389	    const windows = try allocator.alloc(Part, n_children * n);
390	    defer allocator.free(windows);
391	    var total_len: usize = 0;
392	    var maybe_nulls = false;
393	    var view: ArrayData = undefined;
394	    for (parts, 0..) |*part, p| {
395	        const d = partData(part, &view);
396	        // std.meta.eql first: copies of one type (parts sliced from one array) share its pointers.
397	        if (!std.meta.eql(d.data_type, dt) and !datatype.dataTypeEql(d.data_type, dt)) return error.InvalidInput;
398	        if (d.buffers.len < buf_count or d.children.len != n_children) return error.InvalidInput;
399	        total_len = std.math.add(usize, total_len, d.length) catch return error.InvalidInput;
400	        maybe_nulls = maybe_nulls or ((d.null_count orelse 1) != 0 and !d.buffers[0].isEmpty());
401	        for (0..n_children) |c| windows[c * n + p] = try childWindow(layout, part, d, c);
402	    }
403	
404	    const used = bitmap.byteLength(total_len);
405	    var validity = try buffer.OwnedBuffer.init(allocator, if (maybe_nulls) used else 0);
406	    errdefer validity.deinit();
407	    const offsets_len = if (offset_width > 0) (total_len + 1) * offset_width else 0;
408	    var offsets = try buffer.OwnedBuffer.initUninit(allocator, offsets_len);
409	    errdefer offsets.deinit();
410	    if (maybe_nulls or offset_width > 0) {
411	        var row: usize = 0;
412	        var pos: usize = 0;
413	        for (parts, 0..) |*part, p| {
414	            const d = partData(part, &view);
415	            if (maybe_nulls) try appendValidityBits(validity.data, row, d);
416	            if (offset_width > 0) { // lists: one child, windows[p] is its range
417	                if (windows[p].len > max_child - pos) return error.InvalidInput;
418	                if (offset_width == 4) rebaseOffsets(i32, offsets.typedSlice(i32), row, pos, d) else rebaseOffsets(i64, offsets.typedSlice(i64), row, pos, d);
419	                pos += windows[p].len;
420	            }
421	            row += d.length;
422	        }
423	    }
424	    switch (offset_width) {
425	        4 => offsets.typedSlice(i32)[0] = 0,
426	        8 => offsets.typedSlice(i64)[0] = 0,
427	        else => {},
428	    }
429	    const null_count = if (maybe_nulls) total_len - bitmap.countSetBit(validity.data, total_len) else 0;
430	
431	    const children = try allocator.alloc(ArrayRef, n_children);
432	    var built: usize = 0;
433	    errdefer {
434	        for (children[0..built]) |*child| child.release();
435	        allocator.free(children);
436	    }
437	    for (children, 0..) |*child, c| {
438	        const child_windows = windows[c * n ..][0..n];
439	        child.* = try concatParts(allocator, child_windows[0].ref.data().data_type, child_windows);
440	        built += 1;
441	    }
442	
443	    var bufs: [2]array_data.SharedBuffer = .{ array_data.SharedBuffer.empty, array_data.SharedBuffer.empty };
444	    errdefer for (&bufs) |*b| b.release();
445	    if (null_count == 0) validity.deinit() else bufs[0] = try validity.toShared(used);
446	    if (offset_width > 0) bufs[1] = try offsets.toShared(offsets_len) else offsets.deinit();
447	
448	    const data = ArrayData{
449	        .data_type = dt,
450	        .length = total_len,
451	        .null_count = null_count,
452	        .buffers = bufs[0..buf_count],
453	        .children = children,
454	    };
455	    try data.validateLayout();
456	    return try ArrayRef.fromOwnedInlineBuffers(allocator, data);
457	}
