459	/// Rows of child `c` that `part` (rows `d`) covers: the list offsets range, the fixed_size_list
460	/// rows times list_size, or the struct rows (row-aligned or parent coordinates).
461	fn childWindow(layout: DataType, part: anytype, d: *const ArrayData, c: usize) Error!Part {
462	    const child = d.children[c];
463	    const cd = child.data();
464	    const r: ByteRange = switch (layout) {
465	        .list, .map => try offsetsRange(i32, d, cd.length),
466	        .large_list => try offsetsRange(i64, d, cd.length),
467	        .fixed_size_list => |f| blk: {
468	            const size = std.math.cast(usize, f.list_size) orelse return error.InvalidInput;
469	            const end = std.math.add(usize, d.offset, d.length) catch return error.InvalidInput;
470	            break :blk .{
471	                .start = std.math.mul(usize, d.offset, size) catch return error.InvalidInput,
472	                .end = std.math.mul(usize, end, size) catch return error.InvalidInput,
473	            };
474	        },
475	        .struct_ => blk: {
476	            // Like ArrayRef.slice: a child as long as the struct node is row-aligned with it.
477	            const node = if (@TypeOf(part) == *const ArrayRef) d else part.ref.data();
478	            const start = if (cd.length == node.length) d.offset - node.offset else d.offset;
479	            break :blk .{ .start = start, .end = std.math.add(usize, start, d.length) catch return error.InvalidInput };
480	        },
481	        else => unreachable,
482	    };
483	    if (r.end > cd.length) return error.InvalidInput;
484	    return .{ .ref = child, .start = r.start, .len = r.end - r.start };
485	}
