487	/// Copies `src[lo..][0..n]` to the front of `dst` in 16-byte chunks when both sides have room
488	/// for the rounded-up length (bytes past `n` in `dst` are scratch); else one @memcpy.
489	inline fn wildCopy(dst: []u8, src: []const u8, lo: usize, n: usize) void {
490	    const rounded = (n + 15) & ~@as(usize, 15);
491	    if (n <= 256 and lo + rounded <= src.len and rounded <= dst.len) {
492	        var k: usize = 0;
493	        while (k < n) : (k += 16) dst[k..][0..16].* = src[lo + k ..][0..16].*;
494	    } else @memcpy(dst[0..n], src[lo..][0..n]);
495	}
