497	/// Appends one string/binary part: offsets `out_offsets[row + 1 ..]` rebased onto `byte_pos`,
498	/// and its bytes at `out_bytes[byte_pos..]`. Returns the new byte position.
499	fn copyBinaryPart(comptime T: type, out_offsets: []T, out_bytes: []u8, row: usize, byte_pos: usize, d: *const ArrayData) Error!usize {
500	    const r = try binaryDataRange(T, d);
501	    rebaseOffsets(T, out_offsets, row, byte_pos, d);
502	    wildCopy(out_bytes[byte_pos..], d.buffers[2].data, r.start, r.end - r.start);
503	    return byte_pos + (r.end - r.start);
504	}
505	
506	/// Writes `d`'s offsets rebased onto `pos` to `out[row + 1 ..][0..d.length]` (after offsetsRange).
507	fn rebaseOffsets(comptime T: type, out: []T, row: usize, pos: usize, d: *const ArrayData) void {
508	    const src = (d.buffers[1].typedSlice(T) catch unreachable)[d.offset .. d.offset + d.length + 1];
509	    // Wrapping math: malformed (non-monotonic) input yields offsets that validateLayout rejects.
510	    const shift: T = @as(T, @intCast(pos)) -% src[0];
511	    for (src[1..], out[row + 1 ..][0..d.length]) |o, *dst| dst.* = o +% shift;
512	}
513	
514	const ByteRange = struct { start: usize, end: usize };
515	
516	fn binaryDataRange(comptime T: type, d: *const ArrayData) Error!ByteRange {
517	    try requireBufferCount(d, 3);
518	    return offsetsRange(T, d, d.buffers[2].len());
519	}
520	
521	/// [offsets[offset], offsets[offset + length]) of an offsets layout, checked against `limit`.
522	fn offsetsRange(comptime T: type, d: *const ArrayData, limit: usize) Error!ByteRange {
523	    const offsets = d.buffers[1].typedSlice(T) catch return error.InvalidInput;
524	    const last = std.math.add(usize, d.offset, d.length) catch return error.InvalidInput;
525	    if (last >= offsets.len) return error.InvalidInput;
526	    const start = std.math.cast(usize, offsets[d.offset]) orelse return error.InvalidInput;
527	    const end = std.math.cast(usize, offsets[last]) orelse return error.InvalidInput;
528	    if (end < start or end > limit) return error.InvalidInput;
529	    return .{ .start = start, .end = end };
530	}
531	
532	/// Writes `data`'s validity bits into zeroed `dst` at bit `dst_off` (all-null parts stay zero).
533	fn appendValidityBits(dst: []u8, dst_off: usize, data: *const ArrayData) ConcatArrayError!void {
534	    if (data.length == 0) return;
535	    if (data.null_count) |count| {
536	        if (count == data.length) return;
537	        if (count == 0) return bitmap.setBits(dst, dst_off, data.length);
538	    }
539	    // Every caller's layout has a top-level bitmap, so read buffers[0] directly (cheaper than validity()).
540	    if (data.buffers.len == 0 or data.buffers[0].isEmpty()) return bitmap.setBits(dst, dst_off, data.length);
541	    const bits = data.buffers[0].data;
542	    if (bitmap.byteLength(data.offset + data.length) > bits.len) return error.InvalidInput;
543	    bitmap.copyBits(dst, dst_off, bits, data.offset, data.length);
544	}
545	
546	fn dataBytesForFixedWidth(data: *const ArrayData, byte_width: usize) ConcatArrayError![]const u8 {
547	    const start = std.math.mul(usize, data.offset, byte_width) catch return error.InvalidInput;
548	    const data_len = std.math.mul(usize, data.length, byte_width) catch return error.InvalidInput;
549	    const end = std.math.add(usize, start, data_len) catch return error.InvalidInput;
550	    if (data.buffers.len < 2) return error.InvalidInput;
551	    if (end > data.buffers[1].len()) return error.InvalidInput;
552	    return data.buffers[1].data[start..end];
553	}
554	
555	fn requireBufferCount(data: *const ArrayData, min_count: usize) ConcatArrayError!void {
556	    if (data.buffers.len < min_count) return error.InvalidInput;
557	}
558	
559	fn requireBitmapBits(buf: array_data.SharedBuffer, bit_len: usize) ConcatArrayError!void {
560	    if (bitmap.byteLength(bit_len) > buf.len()) return error.InvalidInput;
561	}
