166	    pub fn nullCount(self: *Self) usize {
167	        if (self.null_count) |count| return count;
168	        const dt = layoutDataType(self.data_type);
169	        if (dt == .null) {
170	            self.null_count = self.length;
171	            return self.length;
172	        }
173	        const validity_bitmap = self.validity() orelse {
174	            self.null_count = 0;
175	            return 0;
176	        };
177	        const null_count = bitmap.countUnsetBitsInRange(validity_bitmap.data, self.offset, self.offset + self.length);
178	        self.null_count = null_count;
179	        return null_count;
180	    }
