218	    /// True when `xs[k] <= xs[k + 1]` for every k. No early exit, so the compare-and-OR loop
219	    /// vectorizes; a hostile buffer costs the same as a valid one.
220	    fn isNonDecreasing(comptime T: type, xs: []const T) bool {
221	        if (xs.len < 2) return true;
222	        const L = 16;
223	        var bad: @Vector(L, u1) = @splat(0);
224	        var i: usize = 0;
225	        while (i + L < xs.len) : (i += L) {
226	            const a: @Vector(L, T) = xs[i..][0..L].*;
227	            const b: @Vector(L, T) = xs[i + 1 ..][0..L].*;
228	            bad |= @intFromBool(b < a);
229	        }
230	        var tail: u1 = 0;
231	        while (i + 1 < xs.len) : (i += 1) tail |= @intFromBool(xs[i + 1] < xs[i]);
232	        return @reduce(.Or, bad) == 0 and tail == 0;
233	    }
