235	    fn validateOffsetsI32(offsets: []const i32, start: usize, total_len: usize, data_len: usize) ValidationError!void {
236	        const needed_len = std.math.add(usize, total_len, 1) catch return error.InvalidOffsets;
237	        if (offsets.len < needed_len) return error.BufferTooSmall;
238	        // Non-decreasing from a non-negative first offset implies every offset is >= 0.
239	        if (offsets[start] < 0) return error.InvalidOffsets;
240	        if (!isNonDecreasing(i32, offsets[start..needed_len])) return error.InvalidOffsets;
241	        const last = std.math.cast(usize, offsets[needed_len - 1]) orelse return error.InvalidOffsets;
242	        if (last > data_len) return error.InvalidOffsets;
243	    }
