245	    // ListView offsets/sizes are per-element views into the child array.
246	    fn validateOffsetsSizesI32(offsets: []const i32, sizes: []const i32, start: usize, total_len: usize, child_len: usize) ValidationError!void {
247	        if (offsets.len < total_len) return error.BufferTooSmall;
248	        if (sizes.len < total_len) return error.BufferTooSmall;
249	        var i: usize = start;
250	        while (i < total_len) : (i += 1) {
251	            const off = offsets[i];
252	            const size = sizes[i];
253	            if (off < 0 or size < 0) return error.InvalidOffsets;
254	            const off_usize = std.math.cast(usize, off) orelse return error.InvalidOffsets;
255	            const size_usize = std.math.cast(usize, size) orelse return error.InvalidOffsets;
256	            const end = std.math.add(usize, off_usize, size_usize) catch return error.InvalidOffsets;
257	            if (end > child_len) return error.InvalidOffsets;
258	        }
259	    }
