271	    fn readU32Le(bytes: []const u8) u32 {
272	        std.debug.assert(bytes.len >= 4);
273	        return @as(u32, bytes[0]) |
274	            (@as(u32, bytes[1]) << 8) |
275	            (@as(u32, bytes[2]) << 16) |
276	            (@as(u32, bytes[3]) << 24);
277	    }
