421	    ) ValidationError!void {
422	        if (indices.len < end) return error.BufferTooSmall;
423	        var pos = start;
424	        while (pos < end) : (pos += 1) {
425	            if (self.isNull(pos - start)) continue;
426	            const value = indices[pos];
427	            if (value < 0) return error.InvalidOffsets;
