492	    pub fn validateLayout(self: Self) ValidationError!void {
493	        const dt = layoutDataType(self.data_type);
494	
495	        if (self.null_count) |count| {
496	            // null_count can never exceed the number of logical elements.
497	            if (count > self.length) return error.InvalidNullCount;
498	            // Null arrays have no validity bitmap; all elements are implicitly null.
499	            if (dt == .null) {
500	                if (count != self.length) return error.InvalidNullCount;
501	            } else if (!hasTopLevelValidityBitmap(dt)) {
502	                // Union arrays have no validity bitmap; null_count must be 0.
503	                if (count != 0) return error.InvalidNullCount;
504	            } else if (count != 0 and (self.buffers.len == 0 or self.buffers[0].isEmpty())) {
505	                return error.InvalidNullCount;
506	            }
507	        }
508	
509	        const total_len = std.math.add(usize, self.offset, self.length) catch return error.InvalidOffsets;
510	        const has_top_level_validity = hasTopLevelValidityBitmap(dt);
511	        if (has_top_level_validity and self.buffers.len > 0 and !self.buffers[0].isEmpty()) {
512	            const needed = try checkedBitmapByteLength(total_len);
513	            if (self.buffers[0].len() < needed) return error.BufferTooSmall;
514	        }
515	
516	        switch (dt) {
517	            .null => {},
518	            .string_view, .binary_view => {
519	                if (self.buffers.len < 2) return error.InvalidBufferCount;
520	                const variadic = if (self.buffers.len > 2) self.buffers[2..] else &[_]SharedBuffer{};
521	                try validateByteViews(self.buffers[1].data, self.offset, total_len, variadic);
522	            },
523	            .bool => {
524	                if (self.buffers.len < 2) return error.InvalidBufferCount;
525	                const needed = try checkedBitmapByteLength(total_len);
526	                if (self.buffers[1].len() < needed) return error.BufferTooSmall;
527	            },
528	            .list_view, .large_list_view => {
529	                if (self.buffers.len < 3) return error.InvalidBufferCount;
530	                if (self.children.len != 1) return error.InvalidChildren;
531	
532	                const offset_width = offsetByteWidth(dt).?;
533	                if (self.buffers[1].len() % offset_width != 0) return error.InvalidOffsetBuffer;
534	                if (self.buffers[2].len() % offset_width != 0) return error.InvalidOffsetBuffer;
535	
536	                // Views are validated against the child logical length.
537	                const child_len = self.children[0].data().length;
538	                if (offset_width == 4) {
539	                    const offsets = self.buffers[1].typedSlice(i32) catch return error.InvalidOffsetBuffer;
540	                    const sizes = self.buffers[2].typedSlice(i32) catch return error.InvalidOffsetBuffer;
541	                    try validateOffsetsSizesI32(offsets, sizes, self.offset, total_len, child_len);
542	                } else {
543	                    const offsets = self.buffers[1].typedSlice(i64) catch return error.InvalidOffsetBuffer;
544	                    const sizes = self.buffers[2].typedSlice(i64) catch return error.InvalidOffsetBuffer;
545	                    try validateOffsetsSizesI64(offsets, sizes, self.offset, total_len, child_len);
546	                }
547	            },
548	            .string, .binary, .list, .map, .large_string, .large_binary, .large_list => {
549	                if (self.buffers.len < 2) return error.InvalidBufferCount;
550	                const offset_width = offsetByteWidth(dt).?;
551	                if (self.buffers[1].len() % offset_width != 0) return error.InvalidOffsetBuffer;
552	
553	                const is_list = dt == .list or dt == .large_list or dt == .map;
554	                if (is_list) {
555	                    if (self.children.len != 1) return error.InvalidChildren;
556	                } else if (self.buffers.len < 3) {
557	                    return error.InvalidBufferCount;
558	                }
559	
560	                const data_len = if (is_list)
561	                    self.children[0].data().length
562	                else if (self.buffers.len >= 3) self.buffers[2].len() else 0;
563	
564	                if (offset_width == 4) {
565	                    const offsets = self.buffers[1].typedSlice(i32) catch return error.InvalidOffsetBuffer;
566	                    try validateOffsetsI32(offsets, self.offset, total_len, data_len);
567	                } else {
568	                    const offsets = self.buffers[1].typedSlice(i64) catch return error.InvalidOffsetBuffer;
569	                    try validateOffsetsI64(offsets, self.offset, total_len, data_len);
570	                }
571	            },
572	            .fixed_size_list, .struct_ => {
573	                if (self.buffers.len < 1) return error.InvalidBufferCount;
574	                const expected = switch (dt) {
575	                    .fixed_size_list => 1,
576	                    .struct_ => |st| st.fields.len,
577	                    else => 0,
578	                };
579	                if (self.children.len != expected) return error.InvalidChildren;
