613	            },
614	            .run_end_encoded => {
615	                if (self.buffers.len != 0) return error.InvalidBufferCount;
616	                if (self.children.len != 2) return error.InvalidChildren;
617	
618	                const run_ends = self.children[0].data();
619	                const values = self.children[1].data();
620	                const run_end_dt = switch (dt.run_end_encoded.run_end_type.bit_width) {
621	                    16 => if (dt.run_end_encoded.run_end_type.signed) DataType{ .int16 = {} } else return error.InvalidOffsetBuffer,
622	                    32 => if (dt.run_end_encoded.run_end_type.signed) DataType{ .int32 = {} } else return error.InvalidOffsetBuffer,
623	                    64 => if (dt.run_end_encoded.run_end_type.signed) DataType{ .int64 = {} } else return error.InvalidOffsetBuffer,
624	                    else => return error.InvalidOffsetBuffer,
625	                };
626	                if (!std.meta.eql(run_ends.data_type, run_end_dt)) return error.InvalidChildren;
627	                if (run_ends.buffers.len < 2) return error.InvalidChildren;
628	
629	                const byte_width = switch (dt) {
630	                    .run_end_encoded => |ree| ree.run_end_type.bit_width / 8,
631	                    else => 0,
632	                };
633	                if (byte_width == 0) return error.InvalidOffsetBuffer;
634	                if (run_ends.buffers[1].len() % byte_width != 0) return error.InvalidOffsetBuffer;
635	
636	                // One run end per value in the values child.
637	                const run_count = run_ends.length;
638	                if (values.length != run_count) return error.InvalidChildren;
639	
640	                const run_ends_slice_start = run_ends.offset;
641	                const run_ends_slice_end = std.math.add(usize, run_ends.offset, run_ends.length) catch return error.InvalidOffsets;
642	
643	                switch (byte_width) {
644	                    2 => if (dt.run_end_encoded.run_end_type.signed)
645	                        try validateRunEndsSigned(i16, try runEndsWindow(i16, run_ends.buffers[1], run_ends_slice_start, run_ends_slice_end), total_len)
646	                    else
