661	                    if (self.buffers.len < 2) return error.InvalidBufferCount;
662	                    if (byte_width == 0) return error.InvalidOffsetBuffer;
663	                    const needed = std.math.mul(usize, total_len, byte_width) catch return error.BufferTooSmall;
664	                    if (self.buffers[1].len() < needed) return error.BufferTooSmall;
