670	    pub fn validateFull(self: Self) ValidationError!void {
671	        try self.validateLayout();
672	        const dt = layoutDataType(self.data_type);
673	        const total_len = std.math.add(usize, self.offset, self.length) catch return error.InvalidOffsets;
674	
675	        if (self.null_count) |expected_count| {
676	            if (hasTopLevelValidityBitmap(dt) and self.buffers.len > 0 and !self.buffers[0].isEmpty()) {
677	                const validity_bitmap = ValidityBitmap.fromBuffer(self.buffers[0], total_len);
678	                var actual_count: usize = 0;
679	                var i: usize = 0;
680	                while (i < self.length) : (i += 1) {
681	                    if (!(validity_bitmap.isValid(self.offset + i) catch unreachable)) actual_count += 1;
682	                }
683	                if (actual_count != expected_count) return error.InvalidNullCount;
684	            }
685	        }
686	
687	        switch (dt) {
688	            .struct_ => |st| try self.validateStructChildren(st.fields, total_len),
689	            .map => |map_type| try self.validateMapChild(map_type),
690	            .dictionary => |dict| try self.validateDictionaryIndices(dict, self.offset, total_len),
691	            else => {},
692	        }
693	
694	        for (self.children) |child| try child.data().validateFull();
695	        if (self.dictionary) |dict| try dict.data().validateFull();
696	    }
697	};
