1175	            const y: usize = @intCast((b.buffers[1].typedSlice(i32) catch return false)[bj]);
1176	            return rowsEqual(a.dictionary.?.data(), x, b.dictionary.?.data(), y);
1177	        },
1178	        .list, .map, .list_view, .fixed_size_list => {
1179	            var ra: [2]usize = undefined;
1180	            var rb: [2]usize = undefined;
1181	            for ([_]*const ArrayData{ a, b }, [_]usize{ ai, bj }, [_]*[2]usize{ &ra, &rb }) |d, k, r| {
1182	                if (dt == .fixed_size_list) {
1183	                    const size: usize = @intCast(dt.fixed_size_list.list_size);
1184	                    r.* = .{ k * size, k * size + size };
1185	                } else {
1186	                    const o = d.buffers[1].typedSlice(i32) catch return false;
1187	                    const lo: usize = @intCast(o[k]);
1188	                    r.* = if (dt == .list_view) .{ lo, lo + @as(usize, @intCast((d.buffers[2].typedSlice(i32) catch return false)[k])) } else .{ lo, @intCast(o[k + 1]) };
1189	                }
1190	            }
1191	            if (ra[1] - ra[0] != rb[1] - rb[0]) return false;
1192	            for (0..ra[1] - ra[0]) |k| {
1193	                if (!rowsEqual(a.children[0].data(), ra[0] + k, b.children[0].data(), rb[0] + k)) return false;
1194	            }
1195	            return true;
1196	        },
1197	        .string_view, .binary_view => {
1198	            const x = (array_mod.StringViewArray{ .data = a }).value(i) catch return false;
1199	            const y = (array_mod.StringViewArray{ .data = b }).value(j) catch return false;
1200	            return std.mem.eql(u8, x, y);
1201	        },
1202	        .dense_union, .run_end_encoded => {
1203	            if (dt == .dense_union and a.buffers[0].data[ai] != b.buffers[0].data[bj]) return false;
1204	            const x = childRow(a, i);
1205	            const y = childRow(b, j);
1206	            return rowsEqual(x[0], x[1], y[0], y[1]);
1207	        },
1208	        .struct_, .sparse_union => {
1209	            if (dt == .sparse_union and a.buffers[0].data[ai] != b.buffers[0].data[bj]) return false;
1210	            for (a.children, b.children) |ca, cb| {
1211	                const x = if (ca.data().length == a.length) i else ai;
1212	                const y = if (cb.data().length == b.length) j else bj;
1213	                if (!rowsEqual(ca.data(), x, cb.data(), y)) return false;
1214	            }
1215	            return true;
1216	        },
1217	        else => return false,
1218	    }
1219	}
