1221	/// Child array and child row holding logical row `i` of a dense union (int32 offsets) or a
1222	/// run-end encoded array (int32 run ends).
1223	fn childRow(a: *const ArrayData, i: usize) struct { *const ArrayData, usize } {
1224	    const ai = a.offset + i;
1225	    if (a.data_type == .dense_union) {
1226	        const c = std.mem.indexOfScalar(i8, a.data_type.dense_union.type_ids, @bitCast(a.buffers[0].data[ai])).?;
1227	        return .{ a.children[c].data(), @intCast((a.buffers[1].typedSlice(i32) catch unreachable)[ai]) };
1228	    }
1229	    const re = a.children[0].data();
1230	    const ends = (re.buffers[1].typedSlice(i32) catch unreachable)[re.offset..][0..re.length];
1231	    var k: usize = 0;
1232	    while (ends[k] <= ai) k += 1;
1233	    return .{ a.children[1].data(), k };
1234	}
