1236	fn expectRowsMatchSource(out: *const ArrayData, src: *const ArrayData, indices: []const ?usize) !void {
1237	    try out.validateFull();
1238	    try std.testing.expectEqual(indices.len, out.length);
1239	    for (indices, 0..) |maybe, i| {
1240	        if (maybe) |idx| {
1241	            try std.testing.expect(rowsEqual(out, i, src, idx));
1242	        } else switch (out.data_type) {
1243	            .sparse_union => {},
1244	            .dense_union, .run_end_encoded => {
1245	                const x = childRow(out, i);
1246	                try std.testing.expect(x[0].isNull(x[1]));
1247	            },
1248	            else => try std.testing.expect(out.isNull(i)),
1249	        }
1250	    }
1251	}
