1295	    errdefer out.deinit();
1296	    const ints = [_]?i32{ 1, 2, 3, null, 5, 6 };
1297	    const strs = [_]?[]const u8{ "x", "yy", "ccc", "d", null, "ffffffffffffffffff" };
