1299	    // struct{a: int32, b: string}, row 1 null.
1300	    const pair = try makePairStruct(allocator, &.{ true, false, true, true, true, true }, &ints, &strs);
1301	    out.add(pair);
1302	
1303	    // The same struct as rows 1..5 with children in parent coordinates (offset 1, children of 6 rows).
1304	    var view = pair.data().*;
1305	    view.offset = 1;
1306	    view.length = 5;
