1309	
1310	    // dictionary<int32, string>.
1311	    const dict_type = DataType{ .string = {} };
1312	    var dict = try makeStrings(allocator, &.{ "a", "bb", "ccc" });
1313	    defer dict.release();
1314	    var db = try array_mod.DictionaryBuilder.init(allocator, .{ .bit_width = 32, .signed = true }, &dict_type, 6);
1315	    defer db.deinit();
1316	    for ([_]?i64{ 0, null, 2, 1, 0, 2 }) |v| if (v) |x| try db.appendIndex(x) else try db.appendNull();
1317	    out.add(try db.finish(dict));
1318	
1319	    // fixed_size_list<int32, 2>, row 2 null.
1320	    var fvals = try makeInt32Array(allocator, &.{ 0, 1, 2, null, 4, 5, 6, 7, 8, 9, 10, 11 });
1321	    defer fvals.release();
1322	    var fb = try array_mod.FixedSizeListBuilder.init(allocator, nested_int_field, 2);
1323	    defer fb.deinit();
1324	    for ([_]bool{ true, true, false, true, true, true }) |v| if (v) try fb.appendValid() else try fb.appendNull();
1325	    out.add(try fb.finish(fvals));
1326	
1327	    // fixed_size_list<string, 2>: not fixed-width, so the child is taken with expanded indices.
1328	    var fstrs = try makeStrings(allocator, &.{ "a", null, "cc", "d", "", "f", "g", "hh", null, "j", "k", "l" });
1329	    defer fstrs.release();
1330	    var fsb = try array_mod.FixedSizeListBuilder.init(allocator, nested_str_field, 2);
1331	    defer fsb.deinit();
1332	    for ([_]bool{ true, false, true, true, true, true }) |v| if (v) try fsb.appendValid() else try fsb.appendNull();
