1339	    out.add(try bb.finish());
1340	
1341	    // extension over int32 storage.
1342	    var ext_storage = try makeInt32Array(allocator, &ints);
1343	    defer ext_storage.release();
1344	    var eb = try array_mod.ExtensionBuilder.init(allocator, .{ .name = "test.ext", .storage_type = &nested_int32_type });
1345	    defer eb.deinit();
1346	    out.add(try eb.finish(ext_storage));
1347	
1348	    // map<int32, string>: rows of 2, 0, null, 1, 3, 2 entries.
1349	    var entries = try makePairStruct(allocator, &.{ true, true, true, true, true, true, true, true }, &.{ 1, 2, 3, 4, 5, 6, 7, 8 }, &.{ "k1", "k2", "k3", "k4", "k5", "k6", "k7", "k8" });
1350	    defer entries.release();
