1354	    out.add(try mb.finish(entries));
1355	
1356	    // list_view<int32>.
1357	    var lvals = try makeInt32Array(allocator, &.{ 1, 2, null, 4, 5, 6, 7 });
1358	    defer lvals.release();
1359	    var lb = try array_mod.ListViewBuilder.init(allocator, 6, nested_int_field);
1360	    defer lb.deinit();
