77	/// Chunk holding logical row `idx` (< total); tries `hint` first so sorted indices stay O(1).
78	fn chunkOf(starts: []const usize, hint: usize, idx: usize) usize {
79	    if (starts[hint] <= idx and idx < starts[hint + 1]) return hint;
80	    var lo: usize = 0;
81	    var hi: usize = starts.len - 1;
82	    while (lo < hi) {
83	        const mid = lo + (hi - lo) / 2;
84	        if (starts[mid + 1] <= idx) lo = mid + 1 else hi = mid;
85	    }
86	    return lo;
87	}
