717	/// Direct take for string_view/binary_view: gathers the 16-byte views (null index: zeroed view)
718	/// and shares the variadic data buffers, so long views keep their buffer index and offset.
719	fn takeByteViewArray(allocator: std.mem.Allocator, src: *const array_mod.ArrayData, indices: anytype) KernelError!ArrayRef {
720	    if (src.buffers.len < 2) return error.InvalidInput;
721	    const src_end = std.math.add(usize, src.offset, src.length) catch return error.Overflow;
722	    const views = src.buffers[1].data;
723	    if (views.len / 16 < src_end) return error.InvalidInput;
724	    const src_validity = try validityBytes(src, src_end);
725	    try checkIndices(indices, src.length);
726	    const out_len = indices.len;
727	
728	    var out_views = buffer.OwnedBuffer.initUninit(allocator, out_len * 16) catch return error.OutOfMemory;
729	    errdefer out_views.deinit();
730	    const s = std.mem.bytesAsSlice([16]u8, views[src.offset * 16 ..][0 .. src.length * 16]);
731	    for (indices, std.mem.bytesAsSlice([16]u8, out_views.data[0 .. out_len * 16])) |m, *o| o.* = if (@as(?usize, m)) |j| s[j] else @splat(0);
732	    var validity = buffer.OwnedBuffer.init(allocator, bitmap.byteLength(out_len)) catch return error.OutOfMemory;
733	    errdefer validity.deinit();
734	    const null_count = out_len - gatherBits(validity.data, src_validity, src.offset, indices);
735	
736	    const buffers = allocator.alloc(buffer.SharedBuffer, src.buffers.len) catch return error.OutOfMemory;
737	    defer allocator.free(buffers);
738	    @memcpy(buffers[2..], src.buffers[2..]);
739	    buffers[0] = if (null_count == 0) blk: {
740	        validity.deinit();
741	        break :blk buffer.SharedBuffer.empty;
742	    } else validity.toShared(bitmap.byteLength(out_len)) catch return error.OutOfMemory;
743	    errdefer buffers[0].release();
744	    buffers[1] = out_views.toShared(out_len * 16) catch return error.OutOfMemory;
745	    errdefer buffers[1].release();
746	
747	    const out = ArrayRef.fromOwnedInlineBuffers(allocator, .{
748	        .data_type = src.data_type,
749	        .length = out_len,
750	        .null_count = null_count,
751	        .buffers = buffers,
752	    }) catch return error.OutOfMemory;
753	    for (buffers[2..]) |b| _ = b.retain();
754	    return out;
