757	/// Direct take for dense unions: gathers type ids (null index: the first declared type id with a
758	/// null row of that child) and gives every child the list of its rows in output order; the new
759	/// offsets are the running count per child. Children are indexed by the offsets, not by row.
760	fn takeDenseUnionArray(allocator: std.mem.Allocator, src: *const array_mod.ArrayData, indices: anytype) KernelError!ArrayRef {
761	    const uni = storageDataType(src.data_type).dense_union;
762	    const nchildren = src.children.len;
763	    if (src.buffers.len < 2 or nchildren != uni.fields.len or nchildren > 128) return error.InvalidInput;
764	    const src_end = std.math.add(usize, src.offset, src.length) catch return error.Overflow;
765	    const ids = src.buffers[0].data;
766	    const offsets = src.buffers[1].typedSlice(i32) catch return error.InvalidInput;
767	    if (ids.len < src_end or offsets.len < src_end) return error.InvalidInput;
768	    try checkIndices(indices, src.length);
769	    const out_len = indices.len;
770	
771	    // Type id -> child index (0xFF: undeclared); without declared ids the id is the child index.
772	    var child_of: [256]u8 = @splat(0xFF);
773	    if (uni.type_ids.len == 0) {
774	        for (0..nchildren) |c| child_of[c] = @intCast(c);
775	    } else {
776	        if (uni.type_ids.len != nchildren) return error.InvalidInput;
777	        var c = nchildren;
778	        while (c > 0) : (c -= 1) child_of[@as(u8, @bitCast(uni.type_ids[c - 1]))] = @intCast(c - 1); // first id wins
779	    }
780	    const first: u8 = if (uni.type_ids.len > 0) @bitCast(uni.type_ids[0]) else 0;
781	
782	    var out_ids = buffer.OwnedBuffer.initUninit(allocator, out_len) catch return error.OutOfMemory;
783	    errdefer out_ids.deinit();
784	    var out_offsets = buffer.OwnedBuffer.initUninit(allocator, out_len * 4) catch return error.OutOfMemory;
785	    errdefer out_offsets.deinit();
786	    const o = out_offsets.typedSlice(i32)[0..out_len];
787	    var starts: [129]usize = @splat(0); // rows per child, then (prefix sums) where its rows start
788	    for (indices, out_ids.data[0..out_len], o) |m, *id, *off| {
789	        id.* = if (@as(?usize, m)) |j| ids[src.offset + j] else first;
790	        const c = child_of[id.*];
791	        if (c == 0xFF) return error.InvalidInput;
792	        if (@as(?usize, m)) |j| {
793	            const row = std.math.cast(usize, offsets[src.offset + j]) orelse return error.InvalidInput;
794	            if (row >= src.children[c].data().length) return error.InvalidInput;
795	        }
796	        off.* = @intCast(starts[c + 1]);
797	        starts[c + 1] += 1;
798	    }
799	    for (1..nchildren + 1) |c| starts[c] += starts[c - 1];
800	
801	    // Dense indices: child rows are i32 offsets, so u32 holds them.
802	    const E = if (comptime isDense(@TypeOf(indices))) u32 else ?usize;
803	    const rows = allocator.alloc(E, out_len) catch return error.OutOfMemory;
804	    defer allocator.free(rows);
805	    for (indices, out_ids.data[0..out_len], o) |m, id, off| {
806	        const row: E = if (@as(?usize, m)) |j| @intCast(offsets[src.offset + j]) else if (comptime E == u32) unreachable else null;
807	        rows[starts[child_of[id]] + @as(usize, @intCast(off))] = row;
808	    }
809	
810	    const children = allocator.alloc(ArrayRef, nchildren) catch return error.OutOfMemory;
811	    var built: usize = 0;
812	    errdefer {
813	        for (children[0..built]) |*child| child.release();
814	        allocator.free(children);
815	    }
816	    for (src.children, children, 0..) |child, *out, c| {
817	        out.* = try takeChild(allocator, child, @as([]const E, rows[starts[c]..starts[c + 1]]));
818	        built += 1;
819	    }
820	
821	    var buffers: [2]buffer.SharedBuffer = undefined;
822	    buffers[0] = out_ids.toShared(out_len) catch return error.OutOfMemory;
823	    errdefer buffers[0].release();
824	    buffers[1] = out_offsets.toShared(out_len * 4) catch return error.OutOfMemory;
825	    errdefer buffers[1].release();
826	    return ArrayRef.fromOwnedInlineBuffers(allocator, .{
827	        .data_type = src.data_type,
828	        .length = out_len,
829	        .null_count = 0,
830	        .buffers = buffers[0..],
831	        .children = children,
832	    }) catch return error.OutOfMemory;
833	}
