835	/// Direct take for run_end_encoded: each index finds its physical run (binary search over the
836	/// run ends, or a row map for dense takes; child coordinates: row offset + idx); consecutive rows
837	/// of one run (or null indices) become one output run. The values child is taken once with one
838	/// index per output run.
839	fn takeRunEndEncodedArray(allocator: std.mem.Allocator, src: *const array_mod.ArrayData, indices: anytype) KernelError!ArrayRef {
840	    const re = storageDataType(src.data_type).run_end_encoded.run_end_type;
841	    if (!re.signed) return error.InvalidInput;
842	    return switch (re.bit_width) {
843	        16 => takeRunEnds(i16, allocator, src, indices),
844	        32 => takeRunEnds(i32, allocator, src, indices),
845	        64 => takeRunEnds(i64, allocator, src, indices),
846	        else => error.InvalidInput,
847	    };
848	}
