89	/// Take from a chunked datum, appending the output pieces in order. Indices are split into runs
90	/// that stay inside one chunk: few runs (filters, sorted or clustered takes) take each run from
91	/// its chunk with the array kernels; many runs (random takes) concat the chunks once and take
92	/// from that, unless the chunks do not concat (e.g. different dictionaries).
93	fn takeChunked(
94	    allocator: std.mem.Allocator,
95	    chunks: ChunkedArray,
96	    out_type: DataType,
97	    indices: anytype,
98	    pieces: *std.ArrayList(ArrayRef),
99	) KernelError!void {
100	    const n = chunks.numChunks();
101	    if (n == 0) {
102	        // No chunks: only null indices are valid (one null row each).
103	        try pieces.ensureUnusedCapacity(allocator, indices.len);
104	        for (indices) |m| pieces.appendAssumeCapacity(if (@as(?usize, m)) |idx|
105	            try accessors.datumElementArrayAt(allocator, Datum.fromChunked(chunks), idx)
106	        else
107	            try builders.buildNullLikeArray(allocator, out_type, 1));
108	        return;
109	    }
110	    const starts = allocator.alloc(usize, n + 1) catch return error.OutOfMemory;
111	    defer allocator.free(starts);
112	    starts[0] = 0;
113	    for (chunks.chunks(), 0..) |c, i| starts[i + 1] = std.math.add(usize, starts[i], c.data().length) catch return error.Overflow;
114	    try checkIndices(indices, starts[n]);
115	
116	    // ponytail: 64 ~ cost of one kernel call per run vs. one concat row; retune if mixed shapes get hot.
117	    const max_runs = starts[n] / 64;
118	    var runs: usize = 1;
119	    var cur: usize = 0;
120	    var have = false; // the current run holds a non-null index
121	    for (indices) |m| {
122	        const c = chunkOf(starts, cur, @as(?usize, m) orelse continue);
123	        if (have and c != cur) runs += 1;
124	        if (runs > max_runs) break;
125	        cur = c;
126	        have = true;
127	    }
128	    if (n > 1 and runs > max_runs) concat_first: {
129	        var flat = concat_array_refs.concatArrayRefs(allocator, out_type, chunks.chunks()) catch |err| switch (err) {
130	            error.OutOfMemory => return error.OutOfMemory,
131	            else => break :concat_first,
132	        };
133	        defer flat.release();
134	        return appendPiece(allocator, pieces, try takeChild(allocator, flat, indices));
135	    }
136	
137	    const E = @typeInfo(@TypeOf(indices)).pointer.child;
138	    const local = allocator.alloc(E, indices.len) catch return error.OutOfMemory;
139	    defer allocator.free(local);
140	    var run_start: usize = 0;
141	    cur = 0;
142	    have = false;
143	    for (indices, local, 0..) |m, *l, i| {
144	        if (@as(?usize, m)) |idx| {
145	            const c = chunkOf(starts, cur, idx);
146	            if (have and c != cur) {
147	                try appendPiece(allocator, pieces, try takeChild(allocator, chunks.chunk(cur).*, @as([]const E, local[run_start..i])));
148	                run_start = i;
149	            }
150	            cur = c;
151	            have = true;
152	            l.* = if (comptime E == u32) @intCast(idx - starts[c]) else idx - starts[c];
153	        } else l.* = m;
154	    }
155	    try appendPiece(allocator, pieces, try takeChild(allocator, chunks.chunk(cur).*, @as([]const E, local[run_start..])));
156	}
