665	    const child_len = src.children[0].data().length;
666	    const src_end = std.math.add(usize, src.offset, src.length) catch return error.Overflow;
667	    if (offsets.len < src_end or sizes.len < src_end) return error.InvalidInput;
668	    const src_validity = try validityBytes(src, src_end);
