742	    } else validity.toShared(bitmap.byteLength(out_len)) catch return error.OutOfMemory;
743	    errdefer buffers[0].release();
744	    buffers[1] = out_views.toShared(out_len * 16) catch return error.OutOfMemory;
745	    errdefer buffers[1].release();
