850	fn takeRunEnds(comptime T: type, allocator: std.mem.Allocator, src: *const array_mod.ArrayData, indices: anytype) KernelError!ArrayRef {
851	    if (src.children.len != 2) return error.InvalidInput;
852	    const run_ends = src.children[0].data();
853	    if (run_ends.buffers.len < 2) return error.InvalidInput;
854	    const all = run_ends.buffers[1].typedSlice(T) catch return error.InvalidInput;
855	    const ends_end = std.math.add(usize, run_ends.offset, run_ends.length) catch return error.Overflow;
856	    if (all.len < ends_end) return error.InvalidInput;
857	    const ends = all[run_ends.offset..ends_end];
858	    if (src.children[1].data().length != ends.len) return error.InvalidInput;
859	    _ = std.math.add(usize, src.offset, src.length) catch return error.Overflow;
860	    try checkIndices(indices, src.length);
861	    const out_len = indices.len;
862	    if (out_len > std.math.maxInt(T)) return error.InvalidInput;
863	
864	    const P = if (comptime isDense(@TypeOf(indices))) usize else ?usize;
865	    const phys = allocator.alloc(P, out_len) catch return error.OutOfMemory;
866	    defer allocator.free(phys);
867	    var out_ends = buffer.OwnedBuffer.initUninit(allocator, out_len * @sizeOf(T)) catch return error.OutOfMemory;
868	    errdefer out_ends.deinit();
869	    const e = out_ends.typedSlice(T)[0..out_len];
870	    // Dense takes map every window row to its run in one merge pass; sparse ones binary-search.
871	    // ponytail: 1/16 is a guess at where n log(runs) loses to one pass over the window.
872	    const map: ?[]u32 = if (out_len >= src.length / 16 and ends.len <= std.math.maxInt(u32)) try runMap(T, allocator, ends, src.offset, src.length) else null;
873	    defer if (map) |m| allocator.free(m);
874	    const none = std.math.maxInt(usize); // run of a null index
875	    var runs: usize = 0;
876	    var prev: usize = none;
877	    for (indices, 0..) |m, i| {
878	        const k: usize = if (@as(?usize, m)) |idx| (if (map) |rm| rm[idx] else try findRun(T, ends, src.offset + idx)) else none;
879	        if (i == 0 or k != prev) {
880	            phys[runs] = if (comptime P == usize) k else if (k == none) null else k;
881	            runs += 1;
882	        }
883	        e[runs - 1] = @intCast(i + 1);
884	        prev = k;
885	    }
886	
887	    const children = allocator.alloc(ArrayRef, 2) catch return error.OutOfMemory;
888	    errdefer allocator.free(children);
889	    var ends_buffers: [2]buffer.SharedBuffer = .{ buffer.SharedBuffer.empty, out_ends.toShared(runs * @sizeOf(T)) catch return error.OutOfMemory };
890	    children[0] = ArrayRef.fromOwnedInlineBuffers(allocator, .{
891	        .data_type = switch (T) {
892	            i16 => .{ .int16 = {} },
893	            i32 => .{ .int32 = {} },
894	            else => .{ .int64 = {} },
895	        },
896	        .length = runs,
897	        .null_count = 0,
898	        .buffers = ends_buffers[0..],
899	    }) catch {
900	        ends_buffers[1].release();
901	        return error.OutOfMemory;
902	    };
903	    errdefer children[0].release();
904	    children[1] = try takeChild(allocator, src.children[1], @as([]const P, phys[0..runs]));
905	    errdefer children[1].release();
906	    return ArrayRef.fromOwnedInlineBuffers(allocator, .{
907	        .data_type = src.data_type,
908	        .length = out_len,
909	        .null_count = 0,
910	        .buffers = &.{},
911	        .children = children,
912	    }) catch return error.OutOfMemory;
913	}
