915	/// First run whose end is past `pos`. Non-monotone (hostile) run ends still give an in-bounds run.
916	fn findRun(comptime T: type, ends: []const T, pos: usize) KernelError!usize {
917	    const p = std.math.cast(T, pos) orelse return error.InvalidInput;
918	    if (ends.len == 0) return error.InvalidInput;
919	    var base: usize = 0;
920	    var n = ends.len;
921	    while (n > 1) {
922	        const half = n / 2;
923	        if (ends[base + half - 1] <= p) base += half;
924	        n -= half;
925	    }
926	    base += @intFromBool(ends[base] <= p);
927	    if (base == ends.len) return error.InvalidInput;
928	    return base;
929	}
