931	/// Run of every row `offset .. offset + len` (merge walk over the run ends); every row must be covered.
932	fn runMap(comptime T: type, allocator: std.mem.Allocator, ends: []const T, offset: usize, len: usize) KernelError![]u32 {
933	    if (len > 0 and std.math.cast(T, offset + len - 1) == null) return error.InvalidInput;
934	    const map = allocator.alloc(u32, len) catch return error.OutOfMemory;
935	    errdefer allocator.free(map);
936	    var k: usize = 0;
937	    for (map, offset..) |*r, pos| {
938	        while (k < ends.len and ends[k] <= @as(T, @intCast(pos))) k += 1;
939	        if (k == ends.len) return error.InvalidInput;
940	        r.* = @intCast(k);
941	    }
942	    return map;
943	}
