        const src = std.mem.bytesAsSlice([16]u8, d.buffers[1].data[d.offset * 16 ..][0 .. d.length * 16]);
        for (src, std.mem.bytesAsSlice([16]u8, views.data[row * 16 ..][0 .. d.length * 16])) |v, *o| {
            o.* = v;
            const len = std.mem.readInt(u32, v[0..4], .little);
