fn sameBuffers(a: []const array_data.SharedBuffer, b: []const array_data.SharedBuffer) bool {
    if (a.len != b.len) return false;
    for (a, b) |x, y| if (x.data.ptr != y.data.ptr or x.data.len != y.data.len) return false;
    return true;
}

