            switch (layout) {
                .list, .map => rebaseOffsets(i32, offsets.typedSlice(i32), row, pos[0], d),
                .large_list => rebaseOffsets(i64, offsets.typedSlice(i64), row, pos[0], d),
                .list_view => rebaseViews(i32, offsets.typedSlice(i32), sizes.typedSlice(i32), row, pos[0], w.start, d),
                .large_list_view => rebaseViews(i64, offsets.typedSlice(i64), sizes.typedSlice(i64), row, pos[0], w.start, d),
                .dense_union => try rebaseUnionOffsets(offsets.typedSlice(i32)[row..][0..d.length], &child_of, windows[p..], n, &pos, d),
                .run_end_encoded => switch (width) {
                    2 => try rebaseRunEnds(i16, offsets.typedSlice(i16)[pos[0]..][0..w.len], row, w, d),
                    4 => try rebaseRunEnds(i32, offsets.typedSlice(i32)[pos[0]..][0..w.len], row, w, d),
                    else => try rebaseRunEnds(i64, offsets.typedSlice(i64)[pos[0]..][0..w.len], row, w, d),
                },
                else => {},
            }
