            var ends_bufs = [2]array_data.SharedBuffer{ array_data.SharedBuffer.empty, try offsets.toShared(offsets_len) };
            child.* = ArrayRef.fromOwnedInlineBuffers(allocator, .{
                .data_type = switch (width) {
                    2 => .{ .int16 = {} },
                    4 => .{ .int32 = {} },
                    else => .{ .int64 = {} },
                },
                .length = runs,
                .null_count = 0,
                .buffers = &ends_bufs,
            }) catch |err| {
