/// [min, max + 1) of the offsets of the dense union part's rows of child `c`. Every type id must
/// be declared and every offset inside its child.
fn unionRange(d: *const ArrayData, child_of: *const [256]u8, c: usize, limit: usize) Error!ByteRange {
    const offsets = d.buffers[1].typedSlice(i32) catch return error.InvalidInput;
